import{_ as a,o as e,c as t,ai as o}from"./chunks/framework.Ai2o9gNv.js";const i="/assets/image-20250116090935066.CZlSKbVj.png",s="/assets/image-20250116091157505.y7idt2Tc.png",r="/assets/image-20250116091237635.BfchN-ML.png",l="/assets/image-20250116095501501.DWWc8uOv.png",p="/assets/image-20250116095523881.rpcEvgTA.png",m="/assets/image-20250116095646627.cOqWt548.png",g="/assets/image-20250116095730657.CAiM5x9D.png",d="/assets/image-20250116100212297.aTng-z_X.png",c="/assets/image-20250116100026310.C6vVrVhj.png",u="/assets/image-20250116100343797.DwgByfdy.png",h="/assets/image-20250116100642788.ClZyIeP7.png",_="/assets/image-20250116100701709.KELNsNfV.png",S="/assets/image-20250116100720676.Bs8NfMXq.png",b="/assets/image-20250116100749650.CU2Hxcp_.png",x="/assets/image-20250116100943842.U2_iIq05.png",D=JSON.parse('{"title":"Harmony OSNext 端云一体化（1）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOSNext 端云一体化/HarmonyOSNext 端云一体化（1）/HarmonyOSNext 端云一体化（1）.md","filePath":"鸿蒙开发技巧/HarmonyOSNext 端云一体化/HarmonyOSNext 端云一体化（1）/HarmonyOSNext 端云一体化（1）.md","lastUpdated":1737120266000,"__rawMarkdown":"# Harmony OSNext 端云一体化（1）\\n\\n​ Cloud Foundation Kit（云开发服务）可以按需为应用提供云函数、云数据库、云存储等云端服务。应用运行所需的服务器和环境可以皆由云端平台提供，开发者只需关注应用的业务逻辑，而无需关心基础设施（例如：服务器、操作系统、容器等）。\\n\\n​ DevEco Studio 中还提供了[端云一体化开发](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/agc-harmonyos-clouddev-overview-V5)的开发体验，您可以基于统一的技术栈，高效、协同地完成端、云代码的编写、调试、编译和部署，极大提高构建 HarmonyOS 应用和元服务的效率。\\n\\n## 应用场景\\n\\n- **应用后端** 快速构建应用或者元服务的后端服务，从而大幅简化应用开发与运维相关的事务，快速完成应用的构建\\n- **计算密集型任务** 当应用中出现计算密集型任务时，可以在云端及时申请足够的算力来支撑任务的执行。当任务结束时，可以立即释放资源，避免浪费。\\\\*\\\\*\\\\*\\\\*\\n- **适配类应用** 通过 Cloud Foundation Kit 实现协议类型的转换，比如实现 IoT 中不同设备的协议适配。以及接入第三方平台，通过第三方平台提供的接口，实现业务的接入或者协作。\\n- **突发大量访问** 传统架构服务在某些特殊场景下，可能出现大量的访问。为保证业务高峰时，系统能稳定运行，一般需要购买高性能、昂贵的服务器，组建集群负载均衡。但是，当业务回落时，就导致了大量服务器的资源浪费。\\n\\n## 包含的资源\\n\\n端云一体主要包含的资源有\\n\\n- 云函数\\n- 云数据库\\n- 云存储\\n\\n## 适配的项目类型\\n\\n端云一体可以用在开发鸿蒙的**应用**或者是元服务上。因为考虑应用的上架需要软著+备案，而元服务的上架只需要备案。所以后续的教程中为了更加方便学习，我们会在元服务的环境下进行。\\n\\n## 学习流程\\n\\n稍后我们会延续着以下步骤，让大家可以尽可能的掌握端云一体的开发流程。\\n\\n![image-20250116090935066](assets/image-20250116090935066.png)\\n\\n1. [AGC 平台新建元服务](https://juejin.cn/post/7441761663701041161)\\n2. DevEco Studio 新建对应的项目工程\\n3. 云函数的基本使用\\n4. 云数据库的基本使用\\n5. 云存储的基本使用\\n\\n## AGC 平台新建元服务\\n\\n在 AGC 平台上新建服务的具体步骤可以参考这个文章 [HarmonyOS Next 最新 元服务新建到上架全流程](https://juejin.cn/post/7441761663701041161#heading-2)，这里就不再叙述了。\\n\\n## DevEco Studio 新建对应的项目工程\\n\\n本地在使用 DevEco Studio 新建工程时，需要新建的是端云一体化的元服务项目。\\n\\n![image-20250116091157505](assets/image-20250116091157505.png)\\n\\n---\\n\\n此时，你的项目中会看到额外的云端相关的目录结构。\\n\\n![image-20250116091237635](assets/image-20250116091237635.png)\\n\\n> 特别需要注意的是，目前模拟器是不支持运行端云一体的项目的。所以为了方便测试，最好是具体**真机**。\\n\\n## 运行到真机\\n\\n![image-20250116095501501](assets/image-20250116095501501.png)\\n\\n- 测试下云函数\\n\\n![image-20250116095523881](assets/image-20250116095523881.png)\\n\\n- 测试下云数据库\\n\\n  > 还没有在云端配置云数据库，所以此时的测试是没有反应的。\\n\\n  ![image-20250116095646627](assets/image-20250116095646627.png)\\n\\n- 测试下云存储\\n\\n  ![image-20250116095730657](assets/image-20250116095730657.png)\\n\\n## 云端环境一览\\n\\n我们需要知道的是，在本地操作云端的资源时，本质上都是对云端的资源的一些操作。最终的操作成功与否，都会反映到真正的云端环境。\\n\\n我们登录 AGC 平台，然后找到对应的项目。_这里是元服务的名称，不是项目的名称，你的元服务是归属于某个项目的_\\n\\n![image-20250116100212297](assets/image-20250116100212297.png)\\n\\n### 云函数一览\\n\\n云函数其实就是存放后端逻辑的部分。也是我们后期编写后端业务主要区域。\\n\\n![image-20250116100026310](assets/image-20250116100026310.png)\\n\\n### 云数据库一览\\n\\n![image-20250116100343797](assets/image-20250116100343797.png)\\n\\n这里的字段解释如下\\n\\n| 字段     | 说明                                                                                         |\\n| -------- | -------------------------------------------------------------------------------------------- |\\n| 对象类型 | 表示你的数据中用到的实体的类型，比如用户、购物车都是不同的实体类型，也可以理解为你的数据表格 |\\n| 存储区   | 理解为数据库的名称，你可以在这里管理多个存储区-数据库                                        |\\n| 数据     | 你存储的实际的数据                                                                           |\\n\\n- 对象类型\\n\\n  ![image-20250116100642788](assets/image-20250116100642788.png)\\n\\n- 存储区\\n\\n  ![image-20250116100701709](assets/image-20250116100701709.png)\\n\\n- 数据\\n\\n  ![image-20250116100720676](assets/image-20250116100720676.png)\\n\\n### 云存储一览\\n\\n云存储就是存放你物理文件的地方，比如图片、视频、音频等等。\\n\\n![image-20250116100749650](assets/image-20250116100749650.png)\\n\\n## DevEco Studio 中的云端资源\\n\\n小伙伴们应该还记得，我们在新建端云一体云服务的时候，本地工程中也是多了一个文件夹的。 `CloudProgram`\\n\\n![image-20250116100943842](assets/image-20250116100943842.png)\\n\\n它里面的主要目录结构如下。\\n\\n1. **clouddb** 存放数据库相关的文件\\n2. **cloudfunctions** 存放云函数相关的文件\\n3. **cloud-config.json** 存放云端环境相关的配置\\n\\n后期我们开发的思路可以是以下两种方式：\\n\\n1. 全部都在 AGC 平台上操作，如编写云函数逻辑代码、搭建数据库、数据表\\n2. **尽量都在本地 DevEco Studio 工具中编写云函数逻辑代码、调试代码、搭建数据库、数据集表**\\n\\n以上两种方式都可以。但是为了刚好的开发体验，我们是建议使用方式 2.\\n\\n## 总结\\n\\n本文介绍了 HarmonyOS Next 中端云一体化开发的基础概念和环境搭建。通过 Cloud Foundation Kit，开发者可以更便捷地使用云函数、云数据库和云存储等云端服务，从而专注于业务逻辑的开发，而无需过多关注基础设施的搭建和维护。\\n\\n主要内容包括：\\n\\n- 端云一体化的应用场景和主要资源\\n- AGC 平台上创建元服务的流程\\n- DevEco Studio 中创建端云一体化项目的步骤\\n- 云端环境（云函数、云数据库、云存储）的基本介绍\\n- 本地开发环境的目录结构和开发方式建议\\n\\n通过本文的学习，读者可以对 HarmonyOS Next 的端云一体化开发有一个整体的认识，为后续深入学习打下基础。建议开发者优先选\\n\\n择在 DevEco Studio 中进行开发，这样可以获得更好的开发体验。\\n\\n---\\n\\n如果你兴趣想要了解更多的鸿蒙应用开发细节和最新资讯，欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n"}'),f={name:"鸿蒙开发技巧/HarmonyOSNext 端云一体化/HarmonyOSNext 端云一体化（1）/HarmonyOSNext 端云一体化（1）.md"};function q(v,n,y,C,N,O){return e(),t("div",null,[...n[0]||(n[0]=[o("",59)])])}const H=a(f,[["render",q]]);export{D as __pageData,H as default};
